// src/LandingPage.js
import React, { useEffect } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "./context/AuthContext";
import "./styles.css";

const LandingPage = () => {
  const { user, logout } = useAuth();

  useEffect(() => {
    const observerOptions = { threshold: 0.1, rootMargin: "0px 0px -50px 0px" };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) entry.target.classList.add("visible");
      });
    }, observerOptions);

    document.querySelectorAll(".fade-in").forEach((el) => observer.observe(el));

    const handleScroll = () => {
      const navbar = document.querySelector(".navbar");
      navbar.style.backdropFilter = window.scrollY > 50 ? "blur(14px)" : "blur(4px)";
      navbar.style.background =
        window.scrollY > 50
          ? "rgba(5, 5, 5, 0.7)"
          : "rgba(10,10,10,0.4)";
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <>
      <style>{`
        .navbar {
          position: fixed;
          top: 0;
          width: 100%;
          display: flex;
          justify-content: space-between;
          padding: 14px 40px;
          align-items: center;
          z-index: 1000;
          background: rgba(10,10,10,0.4);
          backdrop-filter: blur(8px);
          border-bottom: 1px solid rgba(255,255,255,0.08);
        }

        .nav-container {
          width: 100%;
          display: flex;
          justify-content: space-between;
          align-items: center;
        }

        .logo {
          font-size: 28px;
          font-weight: bold;
          background: linear-gradient(to right, #00eaff, #33ff88);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          cursor: pointer;
        }

        .nav-menu {
          display: flex;
          align-items: center;
          gap: 12px;
        }

        .nav-btn {
          padding: 7px 14px;
          border-radius: 10px;
          border: 1px solid rgba(0,255,180,0.4);
          color: #eaeaea;
          background: rgba(0,0,0,0.35);
          transition: 0.25s ease;
          font-size: 15px;
          text-decoration: none;
        }

        .nav-btn:hover {
          border-color: #00ffaa;
          box-shadow: 0 0 12px rgba(0,255,180,0.6);
          transform: translateY(-2px);
        }

        .btn-logout {
          background: #ff3b3b;
          border: none;
          padding: 7px 14px;
          border-radius: 10px;
          color: white;
          cursor: pointer;
          transition: 0.25s;
        }

        .btn-logout:hover {
          background: #ff0000;
          box-shadow: 0 0 10px red;
        }

        .hero {
          min-height: 100vh;
          display: flex;
          justify-content: center;
          align-items: center;
          text-align: center;
          padding-top: 90px;
        }

        .hero-content h1 {
          font-size: 65px;
          font-weight: bold;
          background: linear-gradient(45deg, #00f2ff, #00ff99, #9d4dff);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          margin-bottom: 15px;
        }

        .hero-content p {
          color: #bfbfbf;
          font-size: 20px;
          margin-bottom: 25px;
        }

        .btn {
          padding: 10px 20px;
          border-radius: 12px;
          border: none;
          cursor: pointer;
          font-size: 17px;
          transition: 0.25s;
          text-decoration: none;
        }

        .btn-primary {
          background: linear-gradient(45deg, #00ffcc, #00c3ff);
          color: black;
        }

        .btn-primary:hover {
          box-shadow: 0 0 18px rgba(0,255,200,0.7);
        }

        .btn-secondary {
          background: rgba(255,255,255,0.18);
          color: white;
          border: 1px solid rgba(255,255,255,0.3);
        }

        .btn-secondary:hover {
          background: rgba(255,255,255,0.28);
          box-shadow: 0 0 14px rgba(255,255,255,0.4);
        }

        .floating-words {
          pointer-events: none;
          position: fixed;
          inset: 0;
          z-index: -1;
          opacity: 0.5;
        }

        .word {
          position: absolute;
          color: #00ffc8;
          font-size: 18px;
          animation: float 8s linear infinite;
        }

        @keyframes float {
          0% { transform: translateY(0); opacity: 0.6; }
          50% { opacity: 1; }
          100% { transform: translateY(-160px); opacity: 0.3; }
        }
      `}</style>

      {/* Navigation */}
      <nav className="navbar">
        <div className="nav-container">
          <div className="logo">CodeGen4Future</div>

          <ul className="nav-menu">
            <li><Link to="/about" className="nav-btn">About</Link></li>
            <li><Link to="/problems" className="nav-btn">Problems</Link></li>
            <li><Link to="/contests" className="nav-btn">Contests</Link></li>
            <li><Link to="/leaderboard" className="nav-btn">Leaderboard</Link></li>

            {user ? (
              <>
                <li><Link to="/profile" className="nav-btn">Profile</Link></li>
                <li><span>Hi, {user.username || user.email}</span></li>
                <li><button className="btn-logout" onClick={logout}>Logout</button></li>
              </>
            ) : (
              <>
                <li><Link to="/login" className="nav-btn">Login</Link></li>
                <li><Link to="/register" className="nav-btn">Register</Link></li>
              </>
            )}
          </ul>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="hero fade-in">
        <div className="hero-content">
          <h1>Code, Compete & Conquer</h1>
          <p>The Future of Competitive Programming Starts Here</p>

          <div className="cta-buttons" style={{ display: "flex", gap: "12px", justifyContent: "center", flexWrap: "wrap" }}>
            <Link to="/problems" className="btn btn-primary">Problems</Link>
            <Link to="/simple-editor" className="btn btn-secondary">Start Coding</Link>
            <Link to="/contests" className="btn btn-primary">Contests</Link>
            <Link to="/duel" className="btn btn-primary">1 vs 1 Duel</Link>
            <Link to="/teams" className="btn btn-primary">Team Battles</Link>
            <Link to="/about" className="btn btn-secondary">Learn More</Link>
          </div>
        </div>
      </section>

      {/* Floating Words */}
      <div className="floating-words">
        {["console.log","return","import","function","class","debug","await","merge","deploy","API"].map((w, i) => (
          <span key={i} className="word" style={{ left: `${10 + i * 8}%`, top: `${20 + i * 5}%`, animationDelay: `${i * 0.8}s` }}>{w}</span>
        ))}
      </div>
    </>
  );
};

export default LandingPage;
